import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"OpenRouter","description":"OpenRouter free models — Free Models collection, :free text/vision lists, Key and limits, and how to fill them in MiniTavern.","frontmatter":{"title":"OpenRouter","description":"OpenRouter free models — Free Models collection, :free text/vision lists, Key and limits, and how to fill them in MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"OpenRouter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenRouter free models — Free Models collection, :free text/vision lists, Key and limits, and how to fill them in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/free-cloud/openrouter"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/free-cloud/openrouter"}]]},"headers":[],"relativePath":"en/free-cloud/openrouter.md","filePath":"en/free-cloud/openrouter.md","lastUpdated":1787224147000}'),d={name:"en/free-cloud/openrouter.md"};function n(i,e,l,s,c,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h1><p>A global model aggregator: one API Key for many models. Part of the catalog is a <strong>free pool</strong> (IDs often end with <code>:free</code>, or marked Free), good for personal trials, comparing open-source models, and light roleplay. Official collection: <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a>; third-party summary: <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a> (unofficial — trust the OpenRouter console).</p><blockquote><p>Free lists and RPM / daily caps change. <strong>Trust <a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models</a> and your account page</strong>.</p></blockquote><h2 id="sites-and-entry-points" tabindex="-1">Sites and entry points <a class="header-anchor" href="#sites-and-entry-points" aria-label="Permalink to &quot;Sites and entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Site</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a></td></tr><tr><td>API Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free Models collection</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">openrouter.ai/collections/free-models</a></td></tr><tr><td>Model plaza (filter Free)</td><td><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models?q=free</a></td></tr><tr><td>Community summary (third-party)</td><td><a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr><tr><td>API Base URL</td><td><code>https://openrouter.ai/api/v1</code> (usually auto when MiniTavern picks <strong>OpenRouter</strong>)</td></tr></tbody></table><h2 id="how-to-get-free-access" tabindex="-1">How to get free access <a class="header-anchor" href="#how-to-get-free-access" aria-label="Permalink to &quot;How to get free access&quot;">​</a></h2><ol><li>Open <a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a>, register, and create a Key (usually <strong>no credit card</strong>).</li><li>Copy a <strong>Model ID</strong> from <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> or the plaza (watch the <code>:free</code> suffix).</li><li>In MiniTavern pick platform <strong>OpenRouter</strong>, paste the Key, and enter that ID.</li></ol><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Free path</td><td>IDs with <code>:free</code>, or <code>$0</code> models in the collection; or auto-route <code>openrouter/free</code></td></tr><tr><td>Rate limits (reference)</td><td>Often ~<strong>20 RPM / ~50 requests/day</strong>; a one-time top-up of about <strong>$10+</strong> can raise free daily caps to ~<strong>1000/day</strong> (follow official rules)</td></tr><tr><td>Card required</td><td>Free tier usually no; top-up only to raise caps or call paid models</td></tr><tr><td>Privacy</td><td>Some free upstreams may use prompts to improve models; check OpenRouter privacy settings. Poolside Laguna free docs say data may be used for training</td></tr></tbody></table><h2 id="model-list" tabindex="-1">Model list <a class="header-anchor" href="#model-list" aria-label="Permalink to &quot;Model list&quot;">​</a></h2><p>Common <strong>text / vision</strong> IDs from the collection and public summaries (~2026-08); <strong>trust the live site</strong>. IDs are <strong>case-sensitive</strong>; do not drop <code>:free</code> unless that entry has no suffix.</p><h3 id="text-·-auto-route" tabindex="-1">Text · auto-route <a class="header-anchor" href="#text-·-auto-route" aria-label="Permalink to &quot;Text · auto-route&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>openrouter/free</code></td><td>Auto-picks an available free model per request; fastest start, quality varies</td></tr></tbody></table><h3 id="text-·-general-chat" tabindex="-1">Text · general chat <a class="header-anchor" href="#text-·-general-chat" aria-label="Permalink to &quot;Text · general chat&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>meta-llama/llama-3.3-70b-instruct:free</code></td><td>General, multilingual</td></tr><tr><td><code>meta-llama/llama-3.2-3b-instruct:free</code></td><td>Lightweight</td></tr><tr><td><code>openai/gpt-oss-20b:free</code> / <code>openai/gpt-oss-120b:free</code></td><td>OpenAI open-weight MoE</td></tr><tr><td><code>google/gemma-3-27b-it:free</code> / <code>google/gemma-3-12b-it:free</code> / <code>google/gemma-3-4b-it:free</code></td><td>Gemma 3 series</td></tr><tr><td><code>google/gemma-4-31b-it:free</code> / <code>google/gemma-4-26b-a4b-it:free</code></td><td>Gemma 4 (some support vision)</td></tr><tr><td><code>google/gemma-3n-e4b-it:free</code> / <code>google/gemma-3n-e2b-it:free</code></td><td>On-device–oriented light models</td></tr><tr><td><code>qwen/qwen3-next-80b-a3b-instruct:free</code></td><td>Qwen3 chat</td></tr><tr><td><code>z-ai/glm-4.5-air:free</code></td><td>GLM light, Chinese-friendly</td></tr><tr><td><code>minimax/minimax-m2.5:free</code></td><td>MiniMax</td></tr><tr><td><code>nousresearch/hermes-3-llama-3.1-405b:free</code></td><td>Hermes 3</td></tr><tr><td><code>arcee-ai/trinity-large-preview:free</code></td><td>Arcee Trinity Large Preview</td></tr><tr><td><code>openrouter/elephant-alpha</code></td><td>OpenRouter-hosted text (if Free in collection/plaza)</td></tr><tr><td><code>cognitivecomputations/dolphin-mistral-24b-venice-edition:free</code></td><td>Venice Uncensored variant (content policy is on you)</td></tr></tbody></table><h3 id="text-·-reasoning-agent-coding" tabindex="-1">Text · reasoning / Agent / coding <a class="header-anchor" href="#text-·-reasoning-agent-coding" aria-label="Permalink to &quot;Text · reasoning / Agent / coding&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>qwen/qwen3-coder:free</code></td><td>Qwen3 Coder, code-oriented</td></tr><tr><td><code>nvidia/nemotron-3-ultra:free</code> (or current collection ID)</td><td>Nemotron 3 Ultra, long-context Agent</td></tr><tr><td><code>nvidia/nemotron-3.5-lightning:free</code></td><td>High-throughput Agent</td></tr><tr><td><code>nvidia/nemotron-3-super-120b-a12b:free</code></td><td>Nemotron 3 Super</td></tr><tr><td><code>nvidia/nemotron-3-nano-30b-a3b:free</code> / <code>nvidia/nemotron-nano-9b-v2:free</code></td><td>Nano series</td></tr><tr><td><code>poolside/laguna-s-2.1:free</code> / <code>poolside/laguna-xs-2.1:free</code> (plaza IDs)</td><td>Poolside coding Agent; free tier may train on data</td></tr><tr><td><code>cohere/north-mini-code:free</code> (plaza)</td><td>Cohere North coding</td></tr><tr><td><code>liquid/lfm-2.5-1.2b-instruct:free</code> / <code>liquid/lfm-2.5-1.2b-thinking:free</code></td><td>Liquid light</td></tr><tr><td><code>dots-studio/dots3-note-preview:free</code> (plaza)</td><td>Dots3-Note Preview</td></tr></tbody></table><p>Collection sort by usage changes; coding models can also be filtered Free under <a href="https://openrouter.ai/collections/coding" target="_blank" rel="noreferrer">Coding</a>.</p><h3 id="text-·-vision-multimodal-input" tabindex="-1">Text · vision (multimodal input) <a class="header-anchor" href="#text-·-vision-multimodal-input" aria-label="Permalink to &quot;Text · vision (multimodal input)&quot;">​</a></h3><p>If the chat main model supports vision, try with App vision / multimodal:</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>google/gemma-3-27b-it:free</code> and other Gemma 3/4</td><td>Text + image input</td></tr><tr><td><code>nvidia/nemotron-nano-12b-v2-vl:free</code></td><td>Vision / documents</td></tr><tr><td><code>nvidia/nemotron-3-nano-omni:free</code> (plaza)</td><td>Multimodal perception</td></tr><tr><td><code>meta-llama/llama-guard-4-12b:free</code></td><td>Safety classifier — usually not a chat main model</td></tr></tbody></table><h3 id="images-video" tabindex="-1">Images / video <a class="header-anchor" href="#images-video" aria-label="Permalink to &quot;Images / video&quot;">​</a></h3><ul><li><strong>Image gen</strong>: see OpenRouter <a href="https://openrouter.ai/collections/image-models" target="_blank" rel="noreferrer">Image Models</a>; free or not follows each model’s pricing. MiniTavern image link can pick <strong>OpenRouter</strong>.</li><li><strong>Video</strong>: see <a href="https://openrouter.ai/collections/video-models" target="_blank" rel="noreferrer">Video Models</a>; the App <strong>has no built-in video entry</strong>.</li><li>Third-party lists may include Lyria-style music models — unrelated to chat / image gen; do not use as dialogue models.</li></ul><h2 id="how-to-fill-in-minitavern" tabindex="-1">How to fill in MiniTavern <a class="header-anchor" href="#how-to-fill-in-minitavern" aria-label="Permalink to &quot;How to fill in MiniTavern&quot;">​</a></h2><p>General steps: <a href="/ultra_guides/en/manual/model-link">Model link</a>.</p><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>Path: <strong>Settings → Models → Model link → New</strong></p><ol><li>Platform: <strong>OpenRouter</strong> (preset Base URL)</li><li>Paste API Key</li><li>Model ID e.g. <code>meta-llama/llama-3.3-70b-instruct:free</code>, or <code>openrouter/free</code></li><li><strong>Test</strong> → on success, set as default</li></ol><p>You can also use <strong>Custom (OpenAI)</strong> with Base URL <code>https://openrouter.ai/api/v1</code>; prefer the App preset.</p><h3 id="image-gen" tabindex="-1">Image gen <a class="header-anchor" href="#image-gen" aria-label="Permalink to &quot;Image gen&quot;">​</a></h3><p>Path: <strong>Settings → Image gen → Image gen link</strong> → platform <strong>OpenRouter</strong>, pick a plaza ID that supports images and is free (or billing you accept). More reliable free image gen: <a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a>.</p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td><code>HTTP 429</code> / <code>Provider returned error</code></td><td>Free pool full or rate-limited: switch <code>:free</code>, wait, or <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a></td></tr><tr><td>Access fails in mainland China</td><td>Official API may need a proxy; or use mainland-direct vendors / <a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a></td></tr><tr><td>Model 404 / unavailable</td><td>That <code>:free</code> retired: copy a fresh ID from the collection</td></tr></tbody></table><p>More: <a href="/ultra_guides/en/manual/errors">Error codes</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/free-cloud/">Free cloud overview</a></li><li><a href="/ultra_guides/en/free-cloud/freellm">FreeLLM directory</a> — more free vendors</li><li><a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a> — subsidized <code>*-free</code> (including some closed-source mirrors)</li><li><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/en/free-cloud/opencode-zen">OpenCode Zen</a></li><li><a href="/ultra_guides/en/manual/model-link">Model link</a></li><li><a href="/ultra_guides/en/free-cloud/#free-image-generation">Free image gen</a></li></ul>',35)])])}const g=t(d,[["render",n]]);export{m as __pageData,g as default};
